import{_ as e,a0 as n,w as p,s as r,ao as d,I as a,x as t,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"命令行中的世界杯 | LCTT x X-CMD","titleTemplate":false,"description":"命令行中的世界杯 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行中的世界杯 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行中的世界杯 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180627 World Cup football on the command line","title":"命令行中的世界杯","tag":"201807","desc":""},"relativePath":"201807/20180627 World Cup football on the command line.md","filePath":"[post].md"}'),u={name:"201807/20180627 World Cup football on the command line.md"};function g(f,l,b,m,k,h){const s=n("Link");return p(),r("div",null,[l[18]||(l[18]=d('<h1 id="命令行中的世界杯" tabindex="-1">命令行中的世界杯 <a class="header-anchor" href="#命令行中的世界杯" aria-label="Permalink to “命令行中的世界杯”">​</a></h1><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc2018.jpg?resize=700%2C450&amp;ssl=1" alt=""></p><p>足球始终在我们身边。即使我们国家的队伍已经出局（LCTT 译注：显然这不是指我们国家，因为我们根本没有入局……），我还是想知道球赛比分。目前， 国际足联世界杯是世界上最大的足球锦标赛，2018 届是由俄罗斯主办的。每届世界杯都有一些足球强国未能取得参赛资格（LCTT 译注：我要吐槽么？）。意大利和荷兰就无缘本次世界杯。但是即使在未参加比赛的国家，追踪关注最新比分也成为了一种仪式。我希望能及时了解这个世界级的重大赛事最新比分的变化，而不用去搜索不同的网站。</p><p>如果你很喜欢命令行，那么有更好的方法用一个小型命令行程序追踪最新的世界杯比分和排名。让我们看一看最热门的可用的球赛趋势分析程序之一，它叫作 football-cli。</p><p>football-cli 不是一个开创性的应用程序。这几年，有许多命令行工具可以让你了解到最新的球赛比分和赛事排名。例如，我是 soccer-cli （Python 写的）和 App-football （Perl 写的）的重度用户。但我总是在寻找新的趋势分析应用，而 football-cli 在某些方面脱颖而出。</p><p>football-cli 是 JavaScript 开发的，由 Manraj Singh 编写，它是开源的软件。基于 MIT 许可证发布，用 npm（JavaScript 包管理器）安装十分简单。那么，让我们直接行动吧！</p><p>该应用程序提供了命令以获取过去及现在的赛事得分、查看联赛和球队之前和将要进行的赛事。它也会显示某一特定联赛的排名。有一条指令可以列出程序所支持的不同赛事。我们不妨从最后一个条指令开始。</p><p>在 shell 提示符下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football lists</span></span></code></pre></div><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-lists.png?resize=595%2C696&amp;ssl=1" alt="球赛列表"></p><p>世界杯被列在最下方，我错过了昨天的比赛，所以为了了解比分，我在 shell 提示下输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football scores</span></span></code></pre></div><p><img src="https://i2.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc-22.png?resize=634%2C75&amp;ssl=1" alt="football-wc-22"></p><p>现在，我想看看目前的世界杯小组排名。很简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football standings -l WC</span></span></code></pre></div><p>下面是输出的一个片段：</p><p><img src="https://i0.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-wc-table.png?resize=750%2C581&amp;ssl=1" alt="football-wc-biaoge"></p><p>你们当中眼尖的可能会注意到这里有一个错误。比如比利时看上去领先于 G 组，但这是不正确的，比利时和英格兰（截稿前）在得分上打平。在这种情况下，纪律好的队伍排名更高。英格兰收到两张黄牌，而比利时收到三张，因此，英格兰应当名列榜首。</p><p>假设我想知道利物浦 90 天前英超联赛的结果，那么:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>luke@ganges:~$ football fixtures -l PL -d 90 -t &quot;Liverpool&quot;</span></span></code></pre></div><p><img src="https://i1.wp.com/www.linuxlinks.com/wp-content/uploads/2018/06/football-Liverpool.png?resize=749%2C131&amp;ssl=1" alt="足球-利物浦"></p><p>我发现这个程序非常方便。它用一种清晰、整洁而有吸引力的方式显示分数和排名。当欧洲联赛再次开始时，它就更有用了。（事实上 2018-19 冠军联赛已经在进行中）！</p>',22)),a("p",null,[l[1]||(l[1]=t("这几个示例让大家对 football-cli 的实用性有了更深的体会。想要了解更多，请转至开发者的 ",-1)),o(s,{href:"https://github.com/ManrajGrover/football-cli"},{default:i(()=>[...l[0]||(l[0]=[t("GitHub 页面",-1)])]),_:1}),l[2]||(l[2]=t("。足球 ＋ 命令行 ＝ football-cli。",-1))]),l[19]||(l[19]=a("p",null,"如同许多类似的工具一样，该软件从 football-data.org 获取相关数据。这项服务以机器可读的方式为所有欧洲主要联赛提供数据，包括比赛、球队、球员、结果等等。所有这些信息都是以 JOSN 形式通过一个易于使用的 RESTful API 提供的。",-1)),l[20]||(l[20]=a("hr",null,null,-1)),a("p",null,[l[4]||(l[4]=t("via: ",-1)),o(s,{href:"https://www.linuxlinks.com/football-cli-world-cup-football-on-the-command-line/"},{default:i(()=>[...l[3]||(l[3]=[t("https://www.linuxlinks.com/football-cli-world-cup-football-on-the-command-line/",-1)])]),_:1})]),a("p",null,[l[9]||(l[9]=t("作者：",-1)),o(s,{href:"https://www.linuxlinks.com/author/luke-baker/"},{default:i(()=>[...l[5]||(l[5]=[t("Luke Baker",-1)])]),_:1}),l[10]||(l[10]=t(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...l[6]||(l[6]=[t("lujun9972",-1)])]),_:1}),l[11]||(l[11]=t(" 译者：",-1)),o(s,{href:"https://github.com/ZenMoore"},{default:i(()=>[...l[7]||(l[7]=[t("ZenMoore",-1)])]),_:1}),l[12]||(l[12]=t(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...l[8]||(l[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[l[15]||(l[15]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[13]||(l[13]=[t("LCTT",-1)])]),_:1}),l[16]||(l[16]=t(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...l[14]||(l[14]=[t("Linux中国",-1)])]),_:1}),l[17]||(l[17]=t(" 荣誉推出",-1))])])}const T=e(u,[["render",g]]);export{c as __pageData,T as default};
